  model_page: "appendix/info/whistleblower.html",
  short: "Employees can report catastrophic-risk concerns to regulators without retaliation. Complimentary.",
  trigger: "Frontier developers.",
  clocks: { training: "no", internal: "no", release: "no" },
  d_us: { low: 0.00094, central: 0.00445, high: 0.01242 }, d_access: { low: 0.0, central: 0.0013, high: 0.00232 },
