  advocates: {"for": [{"who": "Future of Life Institute", "what": "wrote the 2023 open letter calling for a pause of at least six months, now with more than 31,000 signatures.", "url": "https://futureoflife.org/open-letter/pause-giant-ai-experiments/"}, {"who": "Elon Musk, Steve Wozniak, Yoshua Bengio, Stuart Russell", "what": "were among the letter's best-known signers, 2023.", "url": "https://techxplore.com/news/2023-03-musk-scientists-halt-ai-chatgpt.html"}, {"who": "PauseAI", "what": "campaigns to stop development of the most powerful general AI systems until they can be made safe.", "url": "https://pauseai.info/"}, {"who": "Sen. Bernie Sanders and Rep. Greg Casar", "what": "introduced a bill to pause advanced AI development until a new federal regulator is running, September 2026.", "url": "https://www.sanders.senate.gov/press-releases/news-sanders-casar-introduce-legislation-to-create-new-federal-agency-to-ban-artificial-superintelligence-pause-advanced-ai-development/"}], "against": [{"who": "Bill Gates", "what": "said asking one group to pause doesn't solve the challenges, 2023.", "url": "https://wsau.com/2023/04/04/bill-gates-says-calls-to-pause-ai-wont-solve-challenges/"}, {"who": "Yann LeCun and Andrew Ng", "what": "held a public talk titled Why the 6-month AI Pause is a Bad Idea, 2023.", "url": "https://www.youtube.com/watch?v=BY9KV8uCtj4"}]},
  basis: "model",
  how: "Simulation model, 12 months after the rule takes effect: U.S. progress ends up about 1.5 months behind where it would be; China loses about 7 days more through its dependence on U.S. models, at the \"a little\" setting. Most of the model's inputs are stated assumptions.",
